@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* no minimum from the content: in a dashboard row (repeat(N, 1fr)) the column is the tile's width in
     every status, so a one-line error or an enlarged number cannot widen it in one status only
     (§16.5; week 12 review A11Y-W12-2). Two classes, so the order of the sheets does not matter. */
  .nz-card.nz-kpi-tile {
    min-inline-size: 0;
  }

  .nz-kpi-tile > .nz-metric {
    flex: 1 1 auto;
  }

  .nz-kpi-tile > .nz-metric > .nz-metric-change {
    margin-block-start: auto;
  }
}
